{
  "probability": 0.08,
  "range_low": 0.04,
  "range_high": 0.12,
  "summary": [
    "Posterior probability of Frontier filing for bankruptcy before May 1, 2026 is calibrated at 8% based on Bayesian synthesis of distress signals and liquidity cues.",
    "Anchor draws on ULCC-style distress in the airline sector (distress indicators and ~45% bankruptcy probability), but Frontier-specific factors dampen the risk.",
    "Industry peer distress (Spirit Airlines) increases risk signals, yet Frontier's liquidity cushion and absence of a filing as of May 1, 2026 temper the likelihood.",
    "Overall, risk is elevated relative to general norms but remains modest, with substantial uncertainty about near-term outcomes."
  ],
  "confidence": "low",
  "narrative": "Starting from a high-distress reference class, Frontier’s strong liquidity runway and absence of a bankruptcy filing by 5/1/2026 modestly offset peer-driven pressures. The net Bayes-updating yields a low posterior probability of bankruptcy, acknowledging notable uncertainty in airline industry dynamics.",
  "justification": {
    "anchor": {
      "probability": 0.35,
      "basis": "Reference class anchored on ULCC-like distress and a published peer bankruptcy probability around 45%; Frontier shares similar distress signals but stronger liquidity and no filing temper the risk."
    },
    "factor_updates": [
      {
        "factor": "Frontier Altman Z-Score distress signal",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Z-score of 0.38 signals distress and increases bankruptcy probability within the next two years, pushing outlook higher from baseline."
      },
      {
        "factor": "Frontier liquidity cushion and debt position",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Reported liquidity (~$889m) vs. debt and a cash runway to meet obligations reduces near-term default risk, pulling probability down."
      },
      {
        "factor": "Peer airline distress and industry dynamics (Spirit Airlines)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Spirit’s Chapter 11 and ongoing industry stress exert contagion risk and pressure on Frontier, elevating bankruptcy risk."
      },
      {
        "factor": "Public absence of a Frontier bankruptcy filing by the target date",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Public disclosures showing no filing as of 5/1/2026 reduce the probability signal from distress metrics."
      }
    ],
    "synthesis_rationale": "The final 8% posterior emerges from balancing strong distress signals (up) with mitigating factors (down). Although peer distress raises risk, Frontier’s liquidity and lack of filing provide a downward bias; correlated factors and limited projection horizon justify a cautious, low-probability conclusion with substantial uncertainty."
  }
}

